import { createClient } from 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm';
const supabase=createClient('https://tgxorcblipbjedfjtzmj.supabase.co','sb_publishable_IOYgVpW2Wf5oxekNXFeifw_qP6hmCsM');
const $=s=>document.querySelector(s),esc=s=>{const e=document.createElement('div');e.textContent=s;return e.innerHTML},initial=s=>(s||'?').slice(0,1).toUpperCase();let user,profile,channel,feed;
function note(t){$('#loginInfo').textContent=t}function authMessage(error){if(!error)return'';if(error.message==='Invalid login credentials')return'E-mail ou mot de passe incorrect.';if(error.message.toLowerCase().includes('email not confirmed'))return'Valide d’abord le lien reçu par e-mail, puis reconnecte-toi.';return error.message}function paintProfile(){const n=profile?.is_admin?'Luna':profile?.username||user.email.split('@')[0];['#profileName','#memberName'].forEach(s=>$(s).textContent=n);$('#avatar').textContent=initial(n);$('#connectionState').textContent=profile?.is_admin?'administrateur':'membre'}
async function enter(){const {data:{session}}=await supabase.auth.getSession();if(!session)return;user=session.user;let r=await supabase.from('profiles').select('*').eq('id',user.id).single();profile=r.data;if(!profile){note('Préparation du profil…');return}if(profile.is_admin&&profile.username!=='Luna'){await supabase.from('profiles').update({username:'Luna'}).eq('id',user.id);profile.username='Luna'}document.body.classList.add('signed-in');paintProfile();$('#newRoom').style.display=profile.is_admin?'block':'none';await rooms()}
$('#loginForm').onsubmit=async e=>{e.preventDefault();note('Connexion…');const {error}=await supabase.auth.signInWithPassword({email:$('#loginEmail').value,password:$('#loginPassword').value});note(authMessage(error))};$('#signup').onclick=async()=>{note('Création…');const {error}=await supabase.auth.signUp({email:$('#loginEmail').value,password:$('#loginPassword').value});note(error?authMessage(error):'Compte créé. Vérifie ton e-mail puis connecte-toi.')};
async function rooms(){const {data}=await supabase.from('channels').select('*').order('created_at');const nav=$('#rooms');nav.innerHTML='';data?.forEach(c=>{const b=document.createElement('button');b.className='room';b.innerHTML='<span>#</span> '+esc(c.name);b.onclick=()=>openChannel(c);nav.append(b)});const first=data?.find(c=>!c.is_private)||data?.[0];if(first)openChannel(first)}
async function openChannel(c){if(c.is_private){const code=prompt('Code du salon SAZ :');if(code===null)return;const {data,error}=await supabase.rpc('unlock_saz',{code});if(error||!data){alert(error?.message||'Code incorrect. Après 3 essais, Luna devra te réautoriser.');return}}channel=c;document.querySelectorAll('.room').forEach(b=>b.classList.toggle('active',b.textContent.trim()==='# '+c.name));$('#roomTitle').textContent='# '+c.name;$('header p').textContent=c.description;$('#message').placeholder='Écrire dans # '+c.name;await loadMessages()}
async function loadMessages(){if(!channel)return;feed?.unsubscribe();const {data}=await supabase.from('messages').select('id,body,created_at,user_id,profiles(username)').eq('channel_id',channel.id).order('created_at');$('#messages').innerHTML='';$('#welcome').hidden=!!data?.length;data?.forEach(show);feed=supabase.channel('messages-'+channel.id).on('postgres_changes',{event:'INSERT',schema:'public',table:'messages',filter:'channel_id=eq.'+channel.id},async p=>{const {data}=await supabase.from('messages').select('id,body,created_at,user_id,profiles(username)').eq('id',p.new.id).single();if(data)show(data)}).subscribe()}
function show(m){$('#welcome').hidden=true;const n=m.profiles?.username||'Membre',t=new Date(m.created_at).toLocaleTimeString('fr-BE',{hour:'2-digit',minute:'2-digit'});$('#messages').insertAdjacentHTML('beforeend',`<article class="message"><div class="avatar violet">${esc(initial(n))}</div><div><div class="meta"><strong>${esc(n)}</strong><time>${t}</time></div><p>${esc(m.body)}</p></div></article>`);$('#messages').scrollTop=999999}
$('#form').onsubmit=async e=>{e.preventDefault();const body=$('#message').value.trim();if(!body||!channel)return;$('#message').value='';const {error}=await supabase.from('messages').insert({channel_id:channel.id,user_id:user.id,body});if(error)alert(error.message)};
$('#newRoom').onclick=async()=>{const name=prompt('Nom du nouveau salon :')?.trim();if(!name)return;const {error}=await supabase.from('channels').insert({name,description:'Un salon créé par Luna.',is_private:false});if(error)alert(error.message);else rooms()};
$('#copyLink').onclick=async()=>{await navigator.clipboard.writeText(location.href);$('#copied').textContent='Lien copié !'};$('#editName').onclick=()=>profile?.is_admin?alert('Tu es Luna, administrateur du site.') : alert('Ton identifiant est lié à ton compte.');['#voiceRoom','#openVoice'].forEach(s=>$(s).onclick=()=>$('#voiceDialog').showModal());supabase.auth.onAuthStateChange(()=>enter());enter();

